14	// TestPlanTransfersChainsBalances：统一转账规则按动作原顺序扣款/加款，
15	// 未出现过的收款账户从零开始，同一账户连续收款时后一笔承接前一笔结果，
16	// 金额恰好等于资金库剩余余额时扣款到 0 仍成功。
17	func TestPlanTransfersChainsBalances(t *testing.T) {
18		steps, treasury, balances, err := planTransfers(
19			[]string{"transfer:audits:250", "transfer:audits:100", "transfer:legal:50"},
