30			{"legal", 650, 600, 0, 50},
31		}
32		for i, w := range want {
33			st := steps[i]
34			if st.account != w.acct || st.treasuryBefore != w.tb || st.treasuryAfter != w.ta ||
35				st.recipientBefore != w.rb || st.recipientAfter != w.ra || st.failure != nil {
36				t.Fatalf("step %d = %+v, want acct=%s treasury=%d->%d recipient=%d->%d",
37					i, st, w.acct, w.tb, w.ta, w.rb, w.ra)
38			}
39			if got := st.actionReceipt(i, "transfer:"+w.acct+":x"); got.Treasury.Account != "treasury" ||
40				got.Recipient.Account != w.acct || got.Index != int64(i) {
41				t.Fatalf("actionReceipt shape wrong: %+v", got)
42			}
43		}
44		if treasury != 600 {
45			t.Fatalf("treasury = %d, want 600", treasury)
46		}
47		if balances["audits"] != 350 || balances["legal"] != 50 || len(balances) != 2 {
48			t.Fatalf("balances = %+v, want audits=350 legal=50", balances)
49		}
50	
51		// 起始状态中已有的账户余额被承接，且起始表不被修改。
52		start := map[string]int64{"audits": 7}
53		steps, treasury, balances, err = planTransfers([]string{"transfer:audits:3"}, 10, start)
54		if err != nil {
55			t.Fatalf("planTransfers existing: %v", err)
