72	// TestPlanTransfersFailurePrecedence：动作非法、收款溢出、资金库不足的
73	// 分类、动作位置与先报告顺序沿用首次执行路径的既有行为；同一动作同时
74	// 触发收款溢出与资金库不足时先报告溢出。
75	func TestPlanTransfersFailurePrecedence(t *testing.T) {
76		// 动作格式错误：同时匹配 ErrExecutionRejected 与 ErrInvalidAction。
77		_, _, _, err := planTransfers([]string{"transfer:a:1", "withdraw:b:2"}, 1000, nil)
78		if !errors.Is(err, ErrExecutionRejected) || !errors.Is(err, ErrInvalidAction) {
79			t.Fatalf("malformed err=%v, want both sentinels", err)
80		}
81		if !strings.Contains(err.Error(), `action 1 ("withdraw:b:2")`) {
82			t.Fatalf("malformed error lost position/text: %v", err)
83		}
84	
85		// 收款溢出先于资金库不足：资金库只剩 5、账户已接近 int64 上限，
86		// 一笔 10 同时满足两个条件，必须先报溢出并带动作位置。
87		nearMax := map[string]int64{"a": math.MaxInt64 - 5}
88		_, _, _, err = planTransfers([]string{"transfer:a:10"}, 5, nearMax)
89		if !errors.Is(err, ErrExecutionRejected) || errors.Is(err, ErrInvalidAction) {
90			t.Fatalf("overflow err=%v, want ErrExecutionRejected only", err)
91		}
92		if !strings.Contains(err.Error(), "recipient balance overflow at action 0") ||
