214		}
215		if r.Actions[0].Treasury.Before != 10 || r.Actions[0].Treasury.After != 0 ||
216			r.Actions[0].Recipient.After != 10 {
217			t.Fatalf("exact-remaining receipt: %+v", r.Actions[0])
218		}
219		if bal, _ := store.TreasuryBalance(); bal != 0 {
220			t.Fatalf("treasury = %d, want 0", bal)
221		}
222		if bal, _ := store.Balance("a"); bal != 10 {
223			t.Fatalf("a = %d, want 10", bal)
224		}
225	
226		// 资金库 MaxInt64：先把某账户打到 MaxInt64-5（资金库剩 5），
227		// 再向同一账户转 10 —— 同时溢出且不足，必须先报溢出。
228		big, path2 := openTempStore(t, math.MaxInt64)
229		defer big.Close()
230		mustRegister(t, big, "gip-near", 0, "transfer:a:9223372036854775802")
231		if _, err := big.Execute("gip-near", 0); err != nil {
232			t.Fatalf("setup execute: %v", err)
233		}
234		mustRegister(t, big, "gip-both", 0, "transfer:a:10")
235		_, err = big.Execute("gip-both", 0)
236		if !errors.Is(err, ErrExecutionRejected) || !strings.Contains(err.Error(), "overflow") {
237			t.Fatalf("both-conditions err=%v, want overflow reported first", err)
238		}
239		if bal, _ := big.TreasuryBalance(); bal != 5 {
240			t.Fatalf("treasury changed after failure: %d", bal)
241		}
242		if bal, _ := big.Balance("a"); bal != math.MaxInt64-5 {
243			t.Fatalf("recipient changed after failure: %d", bal)
244		}
245		if rec, ok, _ := big.Receipt("gip-both"); ok || rec != nil {
246			t.Fatalf("receipt left after failure: %+v", rec)
247		}
248		if p, _, _ := big.Proposal("gip-both"); p.State != "passed" {
249			t.Fatalf("state changed after failure: %s", p.State)
250		}
251		// 重开后仍为完整状态：成功凭据与最终余额一致。
252		big.Close()
253		reopened, err := Open(path2)
254		if err != nil {
255			t.Fatalf("reopen: %v", err)
256		}
257		defer reopened.Close()
258		if bal, _ := reopened.TreasuryBalance(); bal != 5 {
259			t.Fatalf("treasury after reopen = %d", bal)
260		}
261	}
