521						s.Close()
522					}
523					t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
524				}
525				if !strings.Contains(err.Error(), tc.want) {
526					t.Fatalf("error %q missing %q", err.Error(), tc.want)
527				}
528				// 原文件保持原样，不被重算结果覆盖。
529				if got, rerr := os.ReadFile(bad); rerr != nil || string(got) != string(tc.raw) {
530					t.Fatalf("corrupt file was modified")
531				}
532			})
533		}
534	}
535	
536	// TestRegisteredAndVotedProposalsTransferIdentically：相同动作与起始余额下，
537	// 登记来源与投票通过来源的提案产生相同的资金变动与逐笔凭据，且已执行
538	// 提案再次执行仍返回首次凭据。
539	func TestRegisteredAndVotedProposalsTransferIdentically(t *testing.T) {
540		actions := []string{"transfer:audits:250", "transfer:audits:100", "transfer:legal:50"}
541	
542		registered, _ := openTempStore(t, 1000)
543		defer registered.Close()
544		mustRegister(t, registered, "gip-r", 0, actions...)
545		rr, err := registered.Execute("gip-r", 0)
546		if err != nil {
547			t.Fatal(err)
548		}
549	
550		voted, _ := openTempStore(t, 1000)
551		defer voted.Close()
552		in := baseVoteInput("gip-v")
553		in.Actions = actions
554		in.StartAt, in.Deadline, in.TimelockEnd = 0, 1, 1
555		mustCreateVote(t, voted, in)
556		if _, err := voted.CastVote("gip-v", "alice", true, 0); err != nil {
557			t.Fatal(err)
558		}
559		if _, err := voted.TallyVote("gip-v", 1); err != nil {
560			t.Fatal(err)
561		}
562		vr, err := voted.Execute("gip-v", 1)
563		if err != nil {
564			t.Fatal(err)
565		}
566	
567		if len(rr.Actions) != len(vr.Actions) {
568			t.Fatalf("receipt action counts differ: %d vs %d", len(rr.Actions), len(vr.Actions))
569		}
570		for i := range rr.Actions {
571			// 两个来源的凭据只有动作原文（编号相同）与双方前后余额可比。
572			ra, va := rr.Actions[i], vr.Actions[i]
573			if ra.Action != va.Action || !reflect.DeepEqual(ra.Treasury, va.Treasury) ||
574				!reflect.DeepEqual(ra.Recipient, va.Recipient) || ra.Index != va.Index {
575				t.Fatalf("action %d differs by source:\nregistered=%+v\nvoted=%+v", i, ra, va)
576			}
577		}
578		for _, pair := range []struct {
579			name    string
580			store   *Store
581			receipt *Receipt
582			id      string
583		}{
584			{"registered", registered, rr, "gip-r"},
585			{"voted", voted, vr, "gip-v"},
586		} {
587			if bal, _ := pair.store.TreasuryBalance(); bal != 600 {
588				t.Fatalf("%s treasury=%d, want 600", pair.name, bal)
589			}
590			if bal, _ := pair.store.Balance("audits"); bal != 350 {
591				t.Fatalf("%s audits=%d, want 350", pair.name, bal)
592			}
593			if bal, _ := pair.store.Balance("legal"); bal != 50 {
594				t.Fatalf("%s legal=%d, want 50", pair.name, bal)
595			}
596			// 再次执行返回首次凭据，不产生二次资金变动。
597			again, err := pair.store.Execute(pair.id, 99999)
598			if err != nil {
599				t.Fatalf("%s re-execute: %v", pair.name, err)
600			}
601			if again.Order != pair.receipt.Order || again.ExecutedAt != pair.receipt.ExecutedAt ||
602				!reflect.DeepEqual(again.Actions, pair.receipt.Actions) {
603				t.Fatalf("%s re-execute changed receipt:\nfirst=%+v\nagain=%+v", pair.name, pair.receipt, again)
604			}
605			if bal, _ := pair.store.TreasuryBalance(); bal != 600 {
606				t.Fatalf("%s treasury changed on retry: %d", pair.name, bal)
607			}
608		}
609	}
610

